*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font:17px/1.55 'Trebuchet MS',sans-serif;scrollbar-color:var(--plum) var(--ground)}::selection{background:var(--plum);color:white}a{color:inherit;text-underline-offset:4px}button,input{font:inherit;accent-color:var(--plum);caret-color:var(--plum)}button{cursor:pointer;min-height:46px;border:1px solid var(--plum);background:transparent;color:var(--ink);border-radius:12px;padding:10px 18px;font-weight:bold}button:hover{background:var(--paper)}button:active{transform:translateY(1px)}button:disabled{cursor:default;color:var(--muted);border-color:var(--line);background:transparent}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--plum);outline-offset:4px}h1,h2{font-family:Fredoka,sans-serif;font-weight:500;line-height:1.05;text-wrap:balance}h1{font-size:clamp(3.8rem,8vw,6rem);letter-spacing:-.03em;margin:0 0 20px}h2{font-size:2rem;margin:0 0 12px}p{max-width:66ch}nav{display:flex;justify-content:space-between;gap:15px;max-width:1240px;margin:auto;padding:20px 30px;border-bottom:1px solid var(--line);font-size:14px}.layout{max-width:1240px;margin:auto;display:grid;grid-template-columns:.8fr 1.2fr;gap:36px;padding:40px 30px 30px;align-items:center}.intro{align-self:center}.intro>p{max-width:31ch}.rule{margin-top:28px;padding:20px 24px;background:var(--butter);border-radius:50% 4% 5% 3% / 4% 5% 4% 6%;transform:rotate(-2deg);max-width:340px}.rule p{margin:0}.rule strong{display:block;margin-bottom:5px}.board{position:relative;max-width:560px;margin:auto;isolation:isolate}.board img{display:block;width:100%;height:auto;aspect-ratio:1}.board svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}.stage-line{display:flex;justify-content:space-between;gap:10px;align-items:center;margin:0 0 4px}.stage-line h2{font-size:1.55rem;margin:0}#round{font-size:14px;white-space:nowrap}#counts{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin:0 0 16px;font-variant-numeric:tabular-nums}.count{background:var(--paper);border-radius:8px;padding:5px 12px;border-bottom:1px solid var(--line);font-size:15px}.count b{font-size:19px;margin-left:4px}.rotation{max-width:500px;margin:auto}.rotation label{display:flex;justify-content:space-between;font-size:15px;font-weight:bold}.rotation output{font-variant-numeric:tabular-nums}input[type=range]{width:100%;min-height:44px;margin:0;cursor:pointer}.turns{display:flex;gap:10px;justify-content:center}.turns button{flex:1}#serve,#next,#replay{background:var(--plum);color:white;border-color:var(--plum)}#serve:hover,#next:hover,#replay:hover{background:var(--ink)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.actions #serve,.actions #next{flex:1}#status{min-height:54px;font-size:16px;margin:14px 0 6px}#hintText{font-size:15px;padding:12px 0;margin:0;color:var(--muted)}[hidden]{display:none!important}.explain{max-width:1180px;margin:20px auto 0;padding:25px 0 35px;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;gap:40px;font-size:15px}.explain p{margin:8px 0}.explain strong{font-family:Fredoka,sans-serif;font-size:22px;font-weight:500}footer{max-width:1180px;margin:0 auto 30px;font-size:14px;color:var(--muted)}#finish{grid-column:1/-1;text-align:center;padding:60px 0}#finish h2{font-size:clamp(2.8rem,7vw,5rem)}#finish p{margin:20px auto}#finish img{width:200px;height:200px;object-fit:cover;display:block;margin:auto}.served .board{animation:serve .45s cubic-bezier(.16,1,.3,1)}@keyframes serve{0%{filter:saturate(1);transform:scale(1)}45%{filter:saturate(1.35);transform:scale(1.025)}100%{filter:saturate(1);transform:scale(1)}}
