<nav><a href="index.php">Chloe Reads Jon</a><span>A little kitchen geometry</span></nav>
<main class="layout" id="game">
<section class="intro"><h1>Fair Slice</h1><p>Same-sized slices. Suspiciously different amounts of meatball.</p><p>Turn the cuts until everyone gets an equal share. Then serve it up.</p><div class="rule"><strong>The house rule:</strong><p>Every slice needs the same number of whole meatballs. No cutting through one. No negotiating with the chef.</p></div></section>
<section aria-label="Pizza puzzle" id="puzzle">
<div class="stage-line"><h2 id="stageTitle" tabindex="-1"></h2><span id="round"></span></div>
<div class="board"><img src="assets/fair-slice/pizza.webp" width="1024" height="1024" alt="An overhead illustration of a golden cheese pizza, with the game's meatballs and cut lines laid over it."><svg id="pizza" viewBox="0 0 500 500" role="img" aria-labelledby="pizzaTitle pizzaDesc"><title id="pizzaTitle">Pizza cuts</title><desc id="pizzaDesc"></desc><g id="sectors"></g><g id="toppings"></g><g id="labels"></g></svg></div>
<div id="counts" aria-label="Meatballs per slice"></div>
<div class="rotation"><label for="angle">Rotate the cuts <output id="degrees" for="angle">0°</output></label><input id="angle" type="range" min="0" max="175" value="0" step="5" aria-describedby="hintText"><div class="turns"><button id="left" aria-label="Rotate cuts anticlockwise by 5 degrees">Turn left</button><button id="right" aria-label="Rotate cuts clockwise by 5 degrees">Turn right</button></div><div class="actions"><button id="serve">Serve this pizza</button><button id="next" hidden>Next pizza</button><button id="hint" aria-expanded="false" aria-controls="hintText">Hint</button><button id="reset">Reset</button></div><p id="status" role="status" aria-live="polite"></p><p id="hintText" hidden></p></div>
</section>
<section id="finish" hidden><img src="assets/fair-slice/pizza.webp" alt="One last golden pizza."><h2 id="finishTitle" tabindex="-1">Everybody got their fair slice.</h2><p>Six pizzas shared. Zero meatball disputes.<br>The chef would like you to know that this is a personal best.</p><button id="replay">Play again</button></section>
</main>
<section class="explain" aria-label="About the puzzle"><div><strong>A fraction of the story</strong><p>The cuts always meet in the middle, so each slice has equal area. But equal area does not guarantee equal toppings. Rotating the cuts changes who gets what without changing the portion size.</p></div><div><strong>From Jon's kitchen</strong><p>Inspired by Jon's <a href="fair-slice.php?source=1">soon-to-be-famous Meatball Pizza</a> post from January 2005. This is a new puzzle, not a reconstruction of his recipe.</p><p>Play together: one person turns the cuts, the other counts. Swap jobs for the next pizza.</p></div></section>
<footer>Made for Jon &amp; Nathan. Original pizza illustration generated with GPT Image. No timer, no scores, just dinner.</footer>
<noscript><p>This pizza needs JavaScript to turn the cuts. Please enable it to play.</p></noscript>
<script>
'use strict';
const levels=[{"n": 2, "each": 2, "solution": 40, "title": "A table for two", "points": [{"a": 192.479, "r": 103.531}, {"a": 97.533, "r": 115.459}, {"a": 262.071, "r": 66.402}, {"a": 239.455, "r": 167.711}]}, {"n": 3, "each": 2, "solution": 25, "title": "One more chair", "points": [{"a": 78.195, "r": 115.587}, {"a": 98.726, "r": 88.336}, {"a": 227.261, "r": 86.821}, {"a": 193.604, "r": 128.001}, {"a": 317.392, "r": 157.932}, {"a": 338.981, "r": 159.656}]}, {"n": 2, "each": 4, "solution": 65, "title": "The crowded half", "points": [{"a": 147.891, "r": 68.168}, {"a": 161.127, "r": 141.385}, {"a": 213.201, "r": 134.577}, {"a": 80.533, "r": 96.089}, {"a": 389.219, "r": 80.144}, {"a": 278.502, "r": 118.87}, {"a": 395.538, "r": 124.483}, {"a": 327.814, "r": 72.662}]}, {"n": 4, "each": 2, "solution": 30, "title": "Four hungry friends", "points": [{"a": 66.456, "r": 128.64}, {"a": 91.442, "r": 87.526}, {"a": 166.716, "r": 72.276}, {"a": 175.201, "r": 129.405}, {"a": 228.914, "r": 77.009}, {"a": 285.731, "r": 98.512}, {"a": 375.926, "r": 156.434}, {"a": 335.579, "r": 66.192}]}, {"n": 3, "each": 3, "solution": 55, "title": "Nine is company", "points": [{"a": 149.999, "r": 69.338}, {"a": 145.402, "r": 163.581}, {"a": 94.677, "r": 137.01}, {"a": 209.113, "r": 150.021}, {"a": 256.263, "r": 66.295}, {"a": 222.765, "r": 67.793}, {"a": 400.262, "r": 154.014}, {"a": 332.011, "r": 67.013}, {"a": 313.594, "r": 121.501}]}, {"n": 4, "each": 3, "solution": 15, "title": "The family feast", "points": [{"a": 64.097, "r": 148.105}, {"a": 88.941, "r": 84.456}, {"a": 90.93, "r": 138.701}, {"a": 153.314, "r": 81.013}, {"a": 133.683, "r": 119.702}, {"a": 164.995, "r": 131.389}, {"a": 263.522, "r": 165.002}, {"a": 218.782, "r": 92.365}, {"a": 254.934, "r": 77.598}, {"a": 305.447, "r": 65.987}, {"a": 358.013, "r": 161.059}, {"a": 356.393, "r": 109.972}]}];
const $=id=>document.getElementById(id), colours=['#7c3b96','#166c61','#a5441c','#3159a1'];
let stage=0,angle=0,solved=false;
const mod=(a,n)=>(a%n+n)%n;
function state(){const l=levels[stage],span=360/l.n,counts=Array(l.n).fill(0);let crossing=0;
 for(const p of l.points){const relative=mod(p.a-angle,360),slot=Math.floor(relative/span),edge=Math.min(relative%span,span-relative%span);counts[slot]++;if(p.r*Math.sin(edge*Math.PI/180)<17)crossing++;}
 return {counts,crossing,fair:counts.every(v=>v===l.each)&&crossing===0};}
function point(r,a){const t=a*Math.PI/180;return [250+r*Math.cos(t),250+r*Math.sin(t)];}
function draw(){const l=levels[stage],span=360/l.n,s=state();let sectors='',labels='';
 for(let i=0;i<l.n;i++){const a=angle+i*span,b=a+span,p=point(209,a),q=point(209,b),label=point(231,a+span/2);sectors+=`<path d="M250 250 L${p} A209 209 0 ${span>180?1:0} 1 ${q} Z" fill="${colours[i]}" fill-opacity=".10"/><path d="M250 250 L${p}" fill="none" stroke="#faf6ff" stroke-width="7"/><path d="M250 250 L${p}" fill="none" stroke="${colours[i]}" stroke-width="2"/>`;labels+=`<circle cx="${label[0]}" cy="${label[1]}" r="15" fill="${colours[i]}"/><text x="${label[0]}" y="${label[1]+5}" text-anchor="middle" fill="white" font-size="16" font-family="sans-serif" font-weight="bold">${i+1}</text>`;}
 $('sectors').innerHTML=sectors;$('labels').innerHTML=labels;
 $('toppings').innerHTML=l.points.map(p=>{const [x,y]=point(p.r,p.a);return `<circle cx="${x}" cy="${y}" r="16" fill="#8c4524" stroke="#542711" stroke-width="2"/><circle cx="${x-4}" cy="${y-4}" r="4" fill="#b56c40"/>`;}).join('');
 $('counts').innerHTML=s.counts.map((n,i)=>`<span class="count" style="border-color:${colours[i]}">Slice ${i+1} <b>${n}</b></span>`).join('');
 $('degrees').value=angle+'°';$('angle').value=angle;
 const description=`${l.n} equal slices; ${l.points.length} meatballs. Clockwise from the right, meatball angles are ${l.points.map(p=>Math.round(p.a%360)+' degrees').join(', ')}. Cuts start at ${angle} degrees. Counts: ${s.counts.join(', ')}. ${s.crossing} meatballs touched by a cut.`;
 $('pizzaDesc').textContent=description;$('angle').setAttribute('aria-valuetext',`${angle} degrees. Slice counts ${s.counts.join(', ')}. ${s.crossing} meatballs touched by a cut.`);
}
function turn(value){if(solved)return;angle=mod(value,360/levels[stage].n);draw();$('status').textContent='Turn the cuts, then serve when the shares look fair.';}
function load(){solved=false;angle=0;const l=levels[stage];$('stageTitle').textContent=l.title;$('round').textContent=`Pizza ${stage+1} of ${levels.length}`;$('angle').max=360/l.n-5;for(const id of ['angle','left','right','serve','hint','reset'])$(id).disabled=false;$('serve').hidden=false;$('next').hidden=true;$('hintText').hidden=true;$('hint').setAttribute('aria-expanded','false');$('hintText').textContent=`Try ${l.solution}°. Each of the ${l.n} slices needs ${l.each} whole meatballs. The numbers go clockwise from the first cut; 0° points right.`;$('status').textContent=`${l.n} diners, ${l.points.length} meatballs. Aim for ${l.each} on every slice.`;draw();}
$('angle').addEventListener('input',e=>turn(Number(e.target.value)));$('left').onclick=()=>turn(angle-5);$('right').onclick=()=>turn(angle+5);
$('serve').onclick=()=>{const s=state();if(!s.fair){$('status').textContent=s.crossing?`${s.crossing} meatball${s.crossing===1?' is':'s are'} on a cut. Turn a little so every meatball stays whole.`:`Not quite: the slices have ${s.counts.join(', ')} meatballs. Aim for ${levels[stage].each} each. Try another angle.`;return;}solved=true;$('next').hidden=false;$('next').textContent=stage===levels.length-1?'Dinner is served':'Next pizza';$('next').focus();$('serve').hidden=true;for(const id of ['angle','left','right','hint','reset'])$(id).disabled=true;$('status').textContent=`Fair and square. Everyone gets ${levels[stage].each} whole meatballs!`;$('puzzle').classList.remove('served');void $('puzzle').offsetWidth;$('puzzle').classList.add('served');};
$('hint').onclick=()=>{const open=$('hintText').hidden;$('hintText').hidden=!open;$('hint').setAttribute('aria-expanded',String(open));};$('reset').onclick=()=>load();
$('next').onclick=()=>{stage++;if(stage===levels.length){$('puzzle').hidden=true;document.querySelector('.intro').hidden=true;$('finish').hidden=false;$('finishTitle').focus();}else{load();$('stageTitle').focus();}};
$('replay').onclick=()=>{stage=0;$('puzzle').hidden=false;document.querySelector('.intro').hidden=false;$('finish').hidden=true;load();$('stageTitle').focus();};load();
</script></body></html>
